-- Demo company fake data — Food Stock
-- Generated for demo/sales purposes. Run in the Supabase SQL editor.
-- Covers Jun-Aug 2026 across all 3 locations (ZC/EC/SC), with a couple of
-- items deliberately run low on stock (Beef Fillet, Fresh Cream) to show
-- the reorder-alert UI, not just a fully healthy picture.


























-- Verification:
select 'food_items' as t, count(*) from food_items where company_id = (select id from companies where slug='demo')
union all select 'food_purchases', count(*) from food_purchases where company_id = (select id from companies where slug='demo')
union all select 'food_issues', count(*) from food_issues where company_id = (select id from companies where slug='demo');
